if (!token) throw new Error('No Lark tenant token: ' + JSON.stringify($json).slice(0, 300));
// An image is a key of input.message_id, or "<message id> <key>" when it sits in another message.
return (input.images || []).slice(0, 10).map((image, i) => {
  const [key, messageId] = image.split(' ').reverse();
  return { json: { key, message_id: messageId || input.message_id, auth: token, index: i + 1, total: Math.min((input.images || []).length, 10) } };
});

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const input = $('When called').first().json;
const now = DateTime.now().setZone(TZ);
// In JSON mode the chain node returns the parsed object; its own "text" key is the post text.
const parse = (j) => {
  if (!j || j.error) return null;
  if (j.is_post !== undefined || j.comments !== undefined || j.author_name !== undefined) return j;
  try { return JSON.parse(String(j.text || '').replace(/```(?:json)?/gi, '')); } catch (e) { return null; }
};
const reads = $input.all().map((i) => parse(i.json)).filter(Boolean);
const s = (v) => (v ?? '').toString().trim();
const first = (k) => reads.map((r) => s(r[k])).find(Boolean) || '';
const maxOf = (k) => { const xs = reads.filter((r) => r[k] !== null && r[k] !== undefined && r[k] !== '').map((r) => Number(r[k])).filter((v) => Number.isFinite(v) && v >= 0); return xs.length ? Math.max(...xs) : null; };
const text = reads.map((r) => s(r.text)).sort((a, b) => b.length - a.length)[0] || '';

let postedAt = null;
for (const r of reads) {
  const d = DateTime.fromISO(s(r.posted_at), { setZone: true });
  if (d.isValid && d <= now.plus({ minutes: 5 })) { postedAt = d.toISO({ suppressMilliseconds: true }); break; }
}
const urls = `${input.text || ''} ${reads.map((r) => s(r.link)).join(' ')}`.match(/https?:\/\/(?:www\.|m\.|web\.)?(?:facebook\.com|fb\.com|fb\.watch)\/\S+/i);
const formats = reads.map((r) => s(r.format)).filter((f) => ['image', 'carousel', 'video', 'reel', 'link', 'live'].includes(f));
const types = ['page', 'profile', 'group'];

const seen = new Set();
const comments = [];
for (const r of reads) {
  for (const c of Array.isArray(r.comments) ? r.comments : []) {
    const k = `${s(c.name)}|${s(c.text)}`;
    if (!s(c.text) || seen.has(k)) continue;
    seen.add(k);
    comments.push(c);
  }
}
const n = (x) => Number(x) || 0;
const commentsText = comments.map((c) => [
  `(${n(c.reactions)} reactions) ${s(c.name)}`,
  s(c.text),
  ...(Array.isArray(c.replies) ? c.replies : []).filter((r) => s(r.text)).map((r) => `  - (${n(r.reactions)} reactions) ${s(r.name)}\n    ${s(r.text).replace(/\n/g, '\n    ')}`),
].join('\n')).join('\n---\n');

const note = s((input.text || '').replace(/https?:\/\/\S+/g, ''));
const images = reads.map((r) => s(r.image_description)).filter(Boolean);
const readable = Boolean(text || comments.length);
const row = {
  post_url: urls ? urls[0].replace(/[)>\].,]+$/, '') : null,
  hook: text.split('\n').map((l) => l.trim()).find(Boolean) || null,
  author_name: first('author_name') || null,
  source_type: types.includes(first('source_type')) ? first('source_type') : null,
  posted_at: postedAt,
  format: formats[0] || (text ? 'text' : null),
  text: [text, reads.some((r) => r.cut_off) ? '(cut off at "Xem thêm" in the screenshot)' : '', images.length ? `[Picture: ${[...new Set(images)].join(' ')}]` : ''].filter(Boolean).join('\n\n') || null,
  reaction_count: maxOf('reaction_count'),
  comment_count: maxOf('comment_count'),
  share_count: maxOf('share_count'),
  comments: commentsText || null,
  notes: note || null,
  captured_at: now.toISO({ suppressMilliseconds: true }),
};
return [{ json: { readable, failed: $input.all().length - reads.length, row, reply_to: input.reply_to } }];

